import{_ as e,o,c as r,a2 as n}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction"},"headers":[],"relativePath":"guide/intro.md","filePath":"guide/intro.md","lastUpdated":1782667185000}'),a={name:"guide/intro.md"};function i(s,t,d,l,c,h){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><strong>Synapse</strong> is a Rust-based intelligent agent development framework, comparable to LangChain and Eino, providing the core building blocks for LLM-powered applications: agents, tools, RAG, multi-agent coordination, MCP, A2A, and WASM sandboxing.</p><h2 id="why-synapse" tabindex="-1">Why Synapse? <a class="header-anchor" href="#why-synapse" aria-label="Permalink to &quot;Why Synapse?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Synapse</th><th>LangChain</th><th>Eino</th></tr></thead><tbody><tr><td>Runnable/Graph/Chain</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>ReAct Agent (multi-turn)</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>MultiAgent patterns</td><td>✅ (4 modes)</td><td>✅</td><td>✅</td></tr><tr><td>RAG with chunking</td><td>✅ (4 splitters)</td><td>✅</td><td>✅</td></tr><tr><td>MCP (Model Context Protocol)</td><td>✅</td><td>✅</td><td>❌</td></tr><tr><td>A2A (Agent-to-Agent)</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>WASM sandbox execution</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Cross-platform (Native + WASM)</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Pure Rust</td><td>✅</td><td>❌</td><td>❌</td></tr></tbody></table><p><strong>Synapse&#39;s unique strengths:</strong></p><ul><li><strong>A2A protocol</strong> — First-class cross-process agent communication</li><li><strong>WASM isolation</strong> — Run agents in <code>wasi</code> sandboxes (PFC runtime)</li><li><strong>MultiAgent 4-mode coverage</strong> — Router, Orchestrator, Handoff, Hybrid</li><li><strong>Type-safe Rust API</strong> — No Python runtime overhead, async-native</li><li><strong>205 tests</strong> — Comprehensive unit + integration coverage, all mocked</li></ul><h2 id="when-to-use-synapse" tabindex="-1">When to Use Synapse? <a class="header-anchor" href="#when-to-use-synapse" aria-label="Permalink to &quot;When to Use Synapse?&quot;">​</a></h2><p>Use Synapse when you need:</p><ul><li>LLM agents with tool use, ReAct, or graph-based orchestration</li><li>RAG pipelines (parsing → chunking → embedding → retrieval)</li><li>Multi-agent systems (routing, decomposition, handoff, hybrid)</li><li>MCP tool integration (stdio or HTTP)</li><li>Cross-process agent communication (A2A)</li><li>Deployment to WASM sandboxes for isolation</li></ul><h2 id="project-status" tabindex="-1">Project Status <a class="header-anchor" href="#project-status" aria-label="Permalink to &quot;Project Status&quot;">​</a></h2><ul><li><strong>Version:</strong> 0.1.0</li><li><strong>License:</strong> Apache 2.0</li><li><strong>Tests:</strong> 205 passing</li><li><strong>Production-ready components:</strong> Core agent/RAG/MCP/A2A/MultiAgent</li><li><strong>Stable APIs:</strong> Yes (semver respected)</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to Go Next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to Go Next&quot;">​</a></h2><ul><li><a href="/guide/quick-start">Quick Start</a> — Build your first agent in 5 minutes</li><li><a href="/concepts/architecture">Architecture</a> — Understand the framework</li><li><a href="/howto/simple-agent">How-to Guides</a> — Step-by-step recipes</li><li><a href="/reference/agent-trait">API Reference</a> — Detailed API docs</li></ul><h2 id="related-projects" tabindex="-1">Related Projects <a class="header-anchor" href="#related-projects" aria-label="Permalink to &quot;Related Projects&quot;">​</a></h2><ul><li><strong>Synapse</strong> (this project) — Agent development toolkit</li><li><strong>Neuron</strong> — LLM serving runtime</li><li><strong>PFC</strong> — Multi-agent orchestrator + WASM sandbox runtime</li></ul>',15)])])}const p=e(a,[["render",i]]);export{g as __pageData,p as default};
